PROGRAM StateMachine
VAR_INPUT
  StartBtn : BOOL;
  StopBtn : BOOL;
  SensorA : BOOL;
  SensorB : BOOL;
  SensorC : BOOL;
  EmergencyStop : BOOL;
END_VAR
VAR_OUTPUT
  ValveA : BOOL;
  ValveB : BOOL;
  ValveC : BOOL;
  ConveyorFwd : BOOL;
  ConveyorRev : BOOL;
  ProcessBusy : BOOL;
  ProcessDone : BOOL;
  FaultLamp : BOOL;
END_VAR
VAR
  Step : INT := 0;
  FillTimerAcc : INT := 0;
  FillTimerPreset : INT := 500;
  FillTimerDone : BOOL := FALSE;
  HeatTimerAcc : INT := 0;
  HeatTimerPreset : INT := 1000;
  HeatTimerDone : BOOL := FALSE;
  ProcessTimerAcc : INT := 0;
  ProcessTimerPreset : INT := 800;
  ProcessTimerDone : BOOL := FALSE;
  DischargeTimerAcc : INT := 0;
  DischargeTimerPreset : INT := 400;
  DischargeTimerDone : BOOL := FALSE;
END_VAR

IF Step = 0 THEN
  ValveA := FALSE; ValveB := FALSE; ValveC := FALSE;
  ConveyorFwd := FALSE; ConveyorRev := FALSE;
  ProcessBusy := FALSE; ProcessDone := FALSE;
  IF StartBtn AND NOT EmergencyStop THEN Step := 10; END_IF
ELSIF Step = 10 THEN
  ValveA := TRUE;
  FillTimerAcc := FillTimerAcc + 1;
  FillTimerDone := FillTimerAcc >= FillTimerPreset;
  IF SensorA OR FillTimerDone THEN
    ValveA := FALSE; FillTimerAcc := 0; Step := 20;
  END_IF
ELSIF Step = 20 THEN
  ValveB := TRUE;
  HeatTimerAcc := HeatTimerAcc + 1;
  HeatTimerDone := HeatTimerAcc >= HeatTimerPreset;
  IF SensorB OR HeatTimerDone THEN
    ValveB := FALSE; HeatTimerAcc := 0; Step := 30;
  END_IF
ELSIF Step = 30 THEN
  ConveyorFwd := TRUE;
  ProcessTimerAcc := ProcessTimerAcc + 1;
  ProcessTimerDone := ProcessTimerAcc >= ProcessTimerPreset;
  IF ProcessTimerDone THEN
    ConveyorFwd := FALSE; ProcessTimerAcc := 0; Step := 40;
  END_IF
ELSIF Step = 40 THEN
  ValveC := TRUE; ConveyorRev := TRUE;
  DischargeTimerAcc := DischargeTimerAcc + 1;
  DischargeTimerDone := DischargeTimerAcc >= DischargeTimerPreset;
  IF SensorC OR DischargeTimerDone THEN
    ValveC := FALSE; ConveyorRev := FALSE; DischargeTimerAcc := 0; Step := 50;
  END_IF
ELSIF Step = 50 THEN
  ProcessDone := TRUE; ProcessBusy := FALSE;
  IF StartBtn THEN Step := 0; END_IF
ELSIF Step = 99 THEN
  FaultLamp := TRUE;
  ValveA := FALSE; ValveB := FALSE; ValveC := FALSE;
  ConveyorFwd := FALSE; ConveyorRev := FALSE; ProcessBusy := FALSE;
  IF NOT EmergencyStop AND StartBtn THEN
    FaultLamp := FALSE; Step := 0;
  END_IF
ELSE
  Step := 0;
END_IF

IF EmergencyStop THEN Step := 99; END_IF
IF Step >= 10 AND Step <= 50 THEN ProcessBusy := TRUE; END_IF
IF Step = 99 THEN
  ValveA := FALSE; ValveB := FALSE; ValveC := FALSE;
  ConveyorFwd := FALSE; ConveyorRev := FALSE;
END_IF

END_PROGRAM
